"""SPEED/EMG bootstrap: no external launchers or environment variables required."""
from pathlib import Path
import os
import sys


def root_directory() -> Path:
    # <Resonance>/python/Lib/site-packages/emg_runtime_bootstrap.py
    root = Path(__file__).absolute().parents[3]
    required = (
        root / "mulines/configured_speed.py",
        root / "mulines/contraction_detector.py",
        root / "params/speed_configurator.txt",
        root / "calib/emg_baseline.json",
        root.parent / "Bridge" / "config.py",
        root.parent / "Bridge" / "emg_game_bridge.py",
    )
    for path in required:
        if not path.is_file():
            raise FileNotFoundError("Required EMG component is missing: " + str(path))
    return root


def build() -> None:
    root = root_directory()
    mod = str(root / "mulines")
    project_root = str(root.parent)
    # Bridge is a sibling package, intentionally outside both Resonance and Game.
    for path in (project_root, mod):
        if path not in sys.path:
            sys.path.insert(0, path)
    os.environ.setdefault("RESONANCE_DIR", str(root))
    from configured_speed import build_configured_speed
    build_configured_speed(root / "params/speed_configurator.txt", root / "calib/emg_baseline.json")
